#!/usr/bin/env node
/**
 * Stamp the deployed build identity into src/build-info.js before Vercel bundles
 * the function (see vercel.json buildCommand).
 *
 * The hash covers only runtime inputs (api/, src/ except this generated file,
 * config.example.json, package.json, vercel.json), so a local checkout can
 * compute the same value and compare it with the deployed /healthz.buildHash.
 * That answers "is production on the same code as HEAD?" without a Vercel token.
 *
 * The script never fails the build: on any error it writes explicit "unknown"
 * values and exits 0, because a failed stamp is better than a failed deploy.
 *
 * Usage:
 *   node scripts/write-build-info.mjs          # rewrite src/build-info.js
 *   node scripts/write-build-info.mjs --print  # print the info, write nothing
 */
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GENERATED = path.join(root, 'src', 'build-info.js');
const STATIC_INPUTS = ['package.json', 'config.example.json', 'vercel.json', path.join('api', 'index.js')];

function listRuntimeFiles() {
  const files = STATIC_INPUTS.map((rel) => path.join(root, rel)).filter((file) => fs.existsSync(file));
  const srcDir = path.join(root, 'src');
  for (const name of fs.readdirSync(srcDir)) {
    if (!name.endsWith('.js')) continue;
    const file = path.join(srcDir, name);
    if (path.resolve(file) === path.resolve(GENERATED)) continue; // generated, not an input
    files.push(file);
  }
  return files.sort();
}

function sourceHash() {
  const hash = createHash('sha256');
  for (const file of listRuntimeFiles()) {
    const rel = path.relative(root, file).split(path.sep).join('/');
    // Normalize CRLF -> LF: the local checkout (core.autocrlf) and the Vercel
    // Linux build must produce the same hash for the same commit.
    const content = Buffer.from(fs.readFileSync(file).toString('utf8').replace(/\r\n/g, '\n'), 'utf8');
    hash.update(rel);
    hash.update('\0');
    hash.update(content);
    hash.update('\0');
  }
  return hash.digest('hex').slice(0, 40);
}

function gitCommit() {
  try {
    return execFileSync('git', ['rev-parse', 'HEAD'], {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  } catch {
    return 'unknown';
  }
}

let info;
try {
  info = {
    commit: process.env.VERCEL_GIT_COMMIT_SHA || gitCommit() || 'unknown',
    buildHash: sourceHash(),
    builtAt: new Date().toISOString(),
  };
} catch (error) {
  info = {
    commit: 'unknown',
    buildHash: 'unknown',
    builtAt: null,
    error: error instanceof Error ? error.message : String(error),
  };
}

if (process.argv.includes('--print')) {
  console.log(JSON.stringify(info, null, 2));
} else {
  const content = [
    '/**',
    ' * GENERATED by scripts/write-build-info.mjs at build time.',
    ' * Committed defaults say "dev"; a deployed instance reports real values here.',
    ' */',
    `export const BUILD = ${JSON.stringify(info, null, 2)};`,
    '',
  ].join('\n');
  fs.writeFileSync(GENERATED, content);
  console.log('[build-info] wrote src/build-info.js', JSON.stringify(info));
}
